INSERT INTO _migration_342_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_fante_b005_006' AND NOT (q.topic_id IS 'topic_was_fante_b005_2' AND q.subject_id IS 'subj_wassce_fante' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Fante: Why should vocabulary meaning be inferred from context?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The core form to which other meaningful elements may be attached","B. Surrounding words and the situation narrow the intended sense","C. Register, collocation and shade of meaning can differ","D. A meaning opposed to another word in the relevant context"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The stated answer applies the governing subject principle directly and distinguishes it from the other same-topic alternatives. Therefore the correct answer is B: Surrounding words and the situation narrow the intended sense.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_fante_b005_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_fante_b005_006' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Fante practice aligned to official Ghana curriculum and WAEC examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/12/Languages17.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
